  private createMatch(): MatchDTO {
    const rating = this.options.playerRating ?? 1000;
    const humans = Math.max(1, Math.min(GAME_CONFIG.maxPlayers, Math.floor(this.options.humanCount)));
    const bots = Math.max(0, Math.min(GAME_CONFIG.maxPlayers - humans, Math.floor(this.options.botCount)));
    const players: PlayerProfile[] = [];
    for (let index = 0; index < humans; index += 1) {
      players.push({
        id: index === 0 ? 'local-player' : 'local-player-' + String(index + 1),
        displayName: index === 0 ? this.options.playerName ?? 'You' : 'Player ' + String(index + 1),
        kind: 'human',
        ballStyleId: this.options.ballStyleId ?? DEFAULT_BALL_ID,
        rating,
      });
    }
    for (const profile of selectBotOpponents(rating, bots, { seed: this.course.id + ':' + String(bots) })) {
      this.botProfiles.set(profile.id, profile);
      players.push({
        id: profile.id,
        displayName: profile.displayName,
        kind: 'bot',
        ballStyleId: DEFAULT_BALL_ID,
        rating: profile.rating,
      });
    }

    const settings = { courseId: this.course.id, maxPlayers: GAME_CONFIG.maxPlayers, strokeLimitPerHole: STROKE_LIMIT };
    let match = this.matchManager.createMatch('match-' + String(Date.now()), settings, players);
    match = this.matchManager.startMatch(match, this.course);

    const startIndex = Math.round(clamp(Math.floor(this.options.startHoleIndex ?? 0), 0, this.course.holes.length - 1));
    const startHole = this.course.holes[startIndex];
    if (startIndex > 0 && startHole) {
      match = {
        ...match,
        currentHoleIndex: startIndex,
        players: match.players.map((player) => ({
          ...player,
          holeScores: [...player.holeScores, this.scoreManager.createHoleScore(player.id, startHole.id)],
        })),
      };
    }
    return match;
  }

  private mountUi(): void {
    this.scoreboard.element.hidden = true;
    this.results.element.hidden = true;
    this.pauseOverlay.element.hidden = true;
    this.toastElement.hidden = true;
    this.hint.textContent = this.hintText();
    this.exitButton.addEventListener('click', () => this.exit());
    this.minimap.setVisible(true);
    this.options.overlayRoot.append(
      this.hud.element,
      this.minimap.element,
      this.hint,
      this.toastElement,
      this.scoreboard.element,
      this.pauseOverlay.element,
      this.results.element,
    );
  }

  private createAimArrow(): THREE.Group {
    const group = new THREE.Group();
    group.name = 'aim-arrow';
    group.visible = false;
    const shaft = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.02, 1), this.aimMaterial);
    shaft.position.z = 0.5;
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.3, 12), this.aimMaterial);
    head.rotation.x = Math.PI / 2;
    head.position.z = 1.05;
    group.add(shaft, head);
    return group;
  }

  private createBallMeshes(): void {
    this.match.players.forEach((player, index) => {
      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color(this.colorOf(player.id, index)),
        roughness: 0.35,
        metalness: 0.05,
      });
      this.ballMaterials.push(material);
      const mesh = new THREE.Mesh(this.ballGeometry, material);
      mesh.name = 'ball-' + player.id;
      mesh.castShadow = true;
      this.ballMeshes.set(player.id, mesh);
      this.sceneManager.addDynamic(mesh);
    });
  }

  private loadHole(index: number): void {
    const hole = this.course.holes[index];
    if (!hole) return;
    const first = this.holeIndex < 0;
    this.holeIndex = index;
    this.hole = hole;
    this.runtime?.dispose();
    this.disposeBall();
    this.runtime = new HoleRuntime(this.physics, hole, this.builder);
    this.sceneManager.addStatic(this.runtime.group);
    this.ball = new GolfBallPhysics(this.physics, hole.spawn, {
      mass: BALL_MASS,
      friction: BALL_FRICTION,
      restitution: BALL_RESTITUTION,
      rollingResistance: 0,
      airResistance: 0,
    });
    this.playerPositions.clear();
    for (const player of this.match.players) {
      this.playerPositions.set(player.id, { ...hole.spawn });
      this.holeSystem.setInitialSafePosition(player.id, hole.spawn);
    }
    this.turnPlayerId = undefined;
    this.botPlan = undefined;
    this.botScheduler.reset();
    this.aim.cancel();
    this.aimPower = 0;
    this.statusText = undefined;
    this.aimArrow.visible = false;
    this.introClock = first ? 0 : -HOLE_SUMMARY_SECONDS;
    this.sceneManager.setSunTarget(new THREE.Vector3(hole.cup.position.x, hole.cup.position.y, hole.cup.position.z));
    this.focusCamera(hole.spawn);
    this.toast('HOLE ' + String(index + 1) + ' · ' + hole.name.toUpperCase() + ' · PAR ' + String(hole.par));
  }

  private advance(dt: number): void {
    if (this.match.currentHoleIndex !== this.holeIndex && this.match.phase !== 'match-results') {
      this.loadHole(this.match.currentHoleIndex);
      return;
    }
    if (this.match.phase === 'hole-intro') {
      this.introClock += dt;
      if (this.introClock >= INTRO_SECONDS) {
        this.match = this.matchManager.beginAiming(this.match, this.hole);
        this.syncTurn();
      }
      return;
    }
    if (this.match.phase === 'aiming') {
      this.updateAiming(dt);
      return;
    }
    if (this.match.phase === 'simulating') this.updateSimulation(dt);
  }

  private updateAiming(dt: number): void {
    const playerId = this.match.activePlayerId;
    if (!playerId || !this.ball) return;
    if (playerId !== this.turnPlayerId) this.syncTurn();

    const bot = this.botProfiles.get(playerId);
    if (bot) {
      const status = this.botScheduler.update(dt);
      this.statusText = status.statusText === '' ? undefined : status.statusText;
      const plan = this.botPlan;
      if (plan && status.showAimLine) {
        this.aimPower = plan.command.normalizedPower * status.progress;
        this.showAim(plan.command.direction, this.aimPower);
      } else if (!status.fireShot) {
        this.aimPower = 0;
        this.aimArrow.visible = false;
      }
      if (status.fireShot && plan) {
        this.botPlan = undefined;
        this.fireShot(playerId, plan.command.direction, plan.command.normalizedPower);
      }
      return;
    }

    const sample = this.aim.update(dt, this.options.input, this.cameraController.state.yaw, true);
    this.aimPower = sample.power;
    this.showAim(sample.direction, sample.power);
    if (sample.fired) {
      this.aim.cancel();
      this.fireShot(playerId, sample.direction, sample.power);
    }
  }

  private updateSimulation(dt: number): void {
    const playerId = this.turnPlayerId;
    if (!playerId || !this.ball) return;
    this.shotClock += dt;
    const position = this.ball.position;

    if (this.holeSystem.isBallHoled(this.hole, position, this.ball.speed)) {
      this.completeHole(playerId);
      return;
    }
    const hazard = this.runtime?.hazardAt(position);
    if (hazard || this.holeSystem.isOutsideBounds(this.hole, position)) {
      this.resetBall(playerId, hazard);
      return;
    }
    if (this.ball.canShoot) {
      this.settleClock += dt;
      if (this.settleClock >= SETTLE_SECONDS) this.finishTurn(playerId, position);
      return;
    }
    this.settleClock = 0;
    if (this.shotClock > SHOT_TIMEOUT_SECONDS) {
      const safe = this.holeSystem.getLastSafePosition(playerId, this.hole.spawn);
      this.ball.reset(safe);
      this.finishTurn(playerId, safe);
    }
  }
